// Installer CLI: the generated recipe registration.
//
// The registration is the one file the composition root learns about installed
// recipes through. It is generated from .recipes/*.yml, never edited: the
// installed set is a build fact, and a hand-edited registration is a second
// source of truth for what is installed.
package installer

import (
	"fmt"
	"go/format"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/calionauta/gogogo/internal/recipe"
)

// recipeRegistrationFile is the generated file buildChiMux calls.
const recipeRegistrationFile = "internal/server/recipes.gen.go"

// registrationEntry is one recipe the file imports and calls.
type registrationEntry struct {
	id    string
	alias string
	path  string
}

// regenerateRegistration rewrites the generated registration from the receipts
// in root. A removed receipt and a receipt with no Register are skipped: the
// first would import a package that is gone, the second contributes no code.
func regenerateRegistration(root string) error {
	formatted, err := registrationContent(root)
	if err != nil {
		return err
	}
	full := filepath.Join(root, filepath.FromSlash(recipeRegistrationFile))
	if merr := os.MkdirAll(filepath.Dir(full), dirMode); merr != nil {
		return &ExitError{code: 1, msg: "recipe: " + merr.Error()}
	}
	if werr := os.WriteFile(full, formatted, scaffoldFileMode); werr != nil {
		return &ExitError{code: 1, msg: "recipe: write registration: " + werr.Error()}
	}
	return nil
}

// registrationContent is the generated file as bytes. Split from the write so
// the freshness gate can compare without touching the tree.
func registrationContent(root string) ([]byte, error) {
	module, err := modulePath(root)
	if err != nil {
		return nil, err
	}
	ids, err := recipe.ListReceipts(root)
	if err != nil {
		return nil, &ExitError{code: 1, msg: "recipe: list receipts: " + err.Error()}
	}
	entries := make([]registrationEntry, 0, len(ids))
	for _, id := range ids {
		r, lerr := recipe.LoadReceipt(root, id)
		if lerr != nil {
			return nil, &ExitError{code: 1, msg: "recipe: read receipt " + id + ": " + lerr.Error()}
		}
		if r.Removed != "" || r.Register == "" {
			continue
		}
		entries = append(entries, registrationEntry{
			id:    id,
			alias: registerAlias(id),
			path:  module + "/" + strings.TrimPrefix(r.Register, "./"),
		})
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].id < entries[j].id })

	formatted, ferr := format.Source([]byte(renderRegistration(entries)))
	if ferr != nil {
		return nil, &ExitError{code: 1, msg: "recipe: the generated registration does not parse: " + ferr.Error()}
	}
	return formatted, nil
}

// modulePath is the import prefix the generated file needs. It reads the tree's
// own go.mod, so the registration works in a renamed project.
func modulePath(root string) (string, error) {
	raw, err := os.ReadFile(filepath.Join(root, "go.mod"))
	if err != nil {
		return "", &ExitError{code: 1, msg: "recipe: " + err.Error() +
			" (the checkout has no go.mod, so the registration cannot name an import path)"}
	}
	for line := range strings.SplitSeq(string(raw), "\n") {
		rest, ok := strings.CutPrefix(strings.TrimSpace(line), "module ")
		if !ok {
			continue
		}
		if mod := strings.TrimSpace(rest); mod != "" {
			return mod, nil
		}
	}
	return "", &ExitError{code: 1, msg: "recipe: go.mod has no module line"}
}

// registerAlias is the Go identifier for one recipe: dashes become underscores,
// and a name that collides with a keyword gets a suffix. The id pattern already
// guarantees a leading letter, so no numeric prefix is possible.
func registerAlias(id string) string {
	alias := strings.ReplaceAll(id, "-", "_")
	if token.Lookup(alias).IsKeyword() {
		return alias + "_recipe"
	}
	return alias
}

// renderRegistration is the whole generated file. format.Source runs over it, so
// this function only has to emit correct Go, not pretty Go.
func renderRegistration(entries []registrationEntry) string {
	var b strings.Builder
	b.WriteString("// Code generated by gogogo recipe install|uninstall. DO NOT EDIT.\n\n")
	b.WriteString("package server\n\n")
	b.WriteString("import (\n")
	b.WriteString("\t\"github.com/calionauta/gogogo/internal/recipe\"\n")
	b.WriteString("\t\"github.com/calionauta/gogogo/internal/recipe/register\"\n")
	for _, e := range entries {
		fmt.Fprintf(&b, "\t%s %q\n", e.alias, e.path)
	}
	b.WriteString(")\n\n")
	b.WriteString("// installedRecipes is regenerated from .recipes/*.yml by `gogogo recipe\n")
	b.WriteString("// install`. A removed receipt is skipped, so uninstalling never leaves an\n")
	b.WriteString("// import of a package that is gone.\n")
	b.WriteString("var installedRecipes = []register.Func{\n")
	for _, e := range entries {
		fmt.Fprintf(&b, "\t%s.Register,\n", e.alias)
	}
	b.WriteString("}\n\n")
	b.WriteString("// registerInstalledRecipes is the one generated call the composition root\n")
	b.WriteString("// makes. The code the recipes register is already in the user's tree; this only\n")
	b.WriteString("// tells the seam what that code claims.\n")
	b.WriteString("func registerInstalledRecipes(reg *recipe.Registry, d register.Deps) {\n")
	b.WriteString("\tfor _, registerRecipe := range installedRecipes {\n")
	b.WriteString("\t\tregisterRecipe(reg, d)\n")
	b.WriteString("\t}\n")
	b.WriteString("}\n")
	return b.String()
}
